'use strict';

// MAIN //

/**
* Updates the winner prototype using LVQ1 update rule.
*
* ## Notes
*
* -   LVQ1 update rule:
*     -   If classification is correct: m_c = m_c + lr * (x - m_c)
*     -   If classification is incorrect: m_c = m_c - lr * (x - m_c)
*
* @private
* @param {PositiveInteger} ndims - number of dimensions
* @param {NumericArray} P - strided array containing prototypes
* @param {PositiveInteger} sp - prototype column stride
* @param {NonNegativeInteger} op - prototype index offset
* @param {NumericArray} V - strided array containing a data point
* @param {PositiveInteger} sv - vector stride
* @param {NonNegativeInteger} ov - vector index offset
* @param {number} lr - learning rate (positive for correct, negative for incorrect classification)
* @returns {NumericArray} strided array containing prototypes
*/
function updatePrototype( ndims, P, sp, op, V, sv, ov, lr ) {
	var delta;
	var pi;
	var i;

	/*
	* LVQ update: P_new = P_old + lr * (V - P_old)
	* When lr is negative (incorrect classification), prototype moves away from input.
	*/
	for ( i = 0; i < ndims; i++ ) {
		pi = P[ op ];
		delta = V[ ov ] - pi;
		pi += lr * delta;
		P[ op ] = pi;

		op += sp;
		ov += sv;
	}
	return P;
}


// EXPORTS //

module.exports = updatePrototype;
